// api:update and api:check: the API surface of each published package (docs/plan.md §13), as the
// declarations a consumer's type checker reads. Each report in docs/api/ holds every `.d.ts` file
// reachable from the package's `types` entry, in the order they are first reached. `tsc -b` must
// run first; `--check` exits non-zero when a report differs from the declarations.

import { readdir } from "node:fs/promises";
import { dirname, join, normalize, relative } from "node:path";

const REPO = join(import.meta.dir, "../../..");
const PACKAGES = join(REPO, "packages");
const REPORTS = join(REPO, "docs/api");

interface Manifest {
  readonly name: string;
  readonly private?: boolean;
  readonly exports: { readonly ".": { readonly types: string } };
}

/** A package's `package.json`, with the fields the report uses checked. */
async function readManifest(path: string): Promise<Manifest> {
  const value: unknown = await Bun.file(path).json();
  if (
    typeof value === "object" &&
    value !== null &&
    "name" in value &&
    typeof value.name === "string" &&
    "exports" in value &&
    typeof value.exports === "object" &&
    value.exports !== null &&
    "." in value.exports &&
    typeof value.exports["."] === "object" &&
    value.exports["."] !== null &&
    "types" in value.exports["."] &&
    typeof value.exports["."].types === "string"
  ) {
    const isPrivate = "private" in value && value.private === true;
    return {
      name: value.name,
      private: isPrivate,
      exports: { ".": { types: value.exports["."].types } },
    };
  }
  throw new Error(`${path}: expected a package with a \`types\` entry for "."`);
}

/** Relative specifiers of `from "…"` and `import("…")` in declaration text. */
const SPECIFIER = /(?:\bfrom\s+|\bimport\s*\()"(\.{1,2}\/[^"]+)"/g;

/** The declaration files reachable from `entry`, breadth first, each with its text. */
async function reachable(entry: string): Promise<ReadonlyMap<string, string>> {
  const files = new Map<string, string>();
  const queue = [entry];
  for (const file of queue) {
    if (files.has(file)) continue;
    // Breadth first on purpose: the order is the report's order.
    // oxlint-disable-next-line no-await-in-loop
    const text = await Bun.file(file).text();
    files.set(file, text);
    for (const [, specifier] of text.matchAll(SPECIFIER)) {
      if (specifier === undefined) continue;
      queue.push(normalize(join(dirname(file), specifier.replace(/\.ts$/, ".d.ts"))));
    }
  }
  return files;
}

/** The report of one package: a Markdown page with one code block per declaration file. */
async function report(directory: string, manifest: Manifest): Promise<string> {
  const dist = join(directory, "dist");
  const files = await reachable(join(directory, manifest.exports["."].types));
  const sections = [...files].map(([file, text]) => {
    const body = text.replace(/\n\/\/# sourceMappingURL=.*\n?$/, "").trimEnd();
    return `## \`${relative(dist, file)}\`\n\n\`\`\`ts\n${body}\n\`\`\`\n`;
  });
  return [
    `# ${manifest.name}: API surface\n`,
    "Generated by `bun run api:update` from the package's declarations: every `.d.ts` file a",
    "consumer's type checker reads, starting at the `types` entry. Don't edit it by hand;",
    "`bun run check` fails while it is stale. A change here is a change to the public API.\n",
    ...sections,
  ].join("\n");
}

/** The report path and contents for each published package, in package-name order. */
async function reports(): Promise<readonly { readonly path: string; readonly contents: string }[]> {
  const names = (await readdir(PACKAGES)).toSorted();
  const all = await Promise.all(
    names.map(async (name) => {
      const directory = join(PACKAGES, name);
      const manifest = await readManifest(join(directory, "package.json"));
      if (manifest.private === true) return undefined;
      const contents = await report(directory, manifest).catch((error: unknown) => {
        throw new Error(`${manifest.name}: no declarations; run \`tsc -b\` first`, {
          cause: error,
        });
      });
      return { path: join(REPORTS, `${name}.md`), contents };
    }),
  );
  return all.filter((each) => each !== undefined);
}

const check = process.argv.includes("--check");
const changed: string[] = [];
for (const { path, contents } of await reports()) {
  const file = Bun.file(path);
  // oxlint-disable-next-line no-await-in-loop
  if ((await file.exists()) && (await file.text()) === contents) continue;
  changed.push(relative(REPO, path));
  // oxlint-disable-next-line no-await-in-loop
  if (!check) await Bun.write(path, contents);
}
if (check && changed.length > 0) {
  console.error(
    `The API surface changed: ${changed.join(", ")}. If that is intended, run \`bun run api:update\` and review the diff.`,
  );
  process.exitCode = 1;
} else if (!check) {
  console.log(
    changed.length > 0 ? `Wrote ${changed.join(", ")}` : "The API reports are up to date",
  );
}
